 SUM(RATE_2), SUM(RATE_3), SUM(RATE_4), SUM(RATE_5), SUM(RATE_AVG) FROM T WHERE FACTORY_DIV = 'A20' GROUP BY FACTORY_DIV ) T2 ORDER BY FACTORY_DIV, DEP_NAME;

